"use client"

import type { FieldErrorProps } from "react-aria-components/FieldError"
import { FieldError as FieldErrorPrimitive } from "react-aria-components/FieldError"
import type { LabelProps } from "react-aria-components/Label"
import { Label as LabelPrimitive } from "react-aria-components/Label"
import { Text, type TextProps } from "react-aria-components/Text"
import { twMerge } from "tailwind-merge"
import { tv } from "tailwind-variants"

import { cx } from "@/lib/primitive"

export const labelStyles = tv({
  base: "select-none text-base/6 text-foreground in-disabled:opacity-50 group-disabled:opacity-50 sm:text-sm/6",
})

export const descriptionStyles = tv({
  base: "block text-muted-foreground text-sm/6 in-disabled:opacity-50 group-disabled:opacity-50",
})

export const fieldErrorStyles = tv({
  base: "block text-destructive/80 text-sm/6 in-disabled:opacity-50 group-disabled:opacity-50 forced-colors:text-[Mark]",
})

export const fieldStyles = tv({
  base: [
    "w-full",
    "[&>[data-slot=label]+[data-slot=control]]:mt-1",
    "[&>[data-slot=label]+[data-slot=control]]:mt-1",
    "[&>[data-slot=label]+[slot='description']]:mt-0",
    "[&>[slot='description']+[data-slot=control]]:mt-1",
    "[&>[data-slot=control]+[slot=description]]:mt-1",
    "[&>[data-slot=control]+[slot=errorMessage]]:mt-1",
    "*:data-[slot=label]:font-medium",
  ],
})

const Label = ({ className, ...props }: LabelProps) => {
  return (
    <LabelPrimitive
      data-slot="label"
      {...props}
      className={labelStyles({ className })}
    />
  )
}

const Description = ({ className, ...props }: TextProps) => {
  return (
    <Text
      {...props}
      slot="description"
      className={descriptionStyles({ className })}
    />
  )
}

const FieldError = ({ className, ...props }: FieldErrorProps) => {
  return (
    <FieldErrorPrimitive
      {...props}
      className={cx(fieldErrorStyles(), className)}
    />
  )
}

const Fieldset = ({
  className,
  ...props
}: React.ComponentProps<"fieldset">) => {
  return (
    <fieldset
      className={twMerge(
        "*:data-[slot=text]:mt-1 [&>*+[data-slot=control]]:mt-5",
        className
      )}
      {...props}
    />
  )
}

const Legend = ({ className, ...props }: React.ComponentProps<"legend">) => {
  return (
    <legend
      data-slot="legend"
      {...props}
      className={twMerge(
        "text-base/6 font-semibold data-disabled:opacity-50",
        className
      )}
    />
  )
}

export { Description, FieldError, Fieldset, Label, Legend }
